"""Render the immutable census snapshot; does not inspect or mutate worktrees."""
import collections,json,pathlib,hashlib
M=pathlib.Path.cwd();P=M/'artifacts/wt1/census.json';d=json.loads(P.read_text())
for r in d['candidates']:
 r['untracked_top_dirs_detail']={k:dict(count=sum(x['path'].split('/')[0]==k for x in r['untracked']),bytes=sum(x['bytes'] for x in r['untracked'] if x['path'].split('/')[0]==k)) for k in r['untracked_top_dirs']}
 r['citation_file_count']=len({h['file'] for h in r['citations']})
 r['unresolved_citation_targets']=len({t['old'] for h in r['citations'] for t in h['targets'] if not t['byte_identical']})
P.write_text(json.dumps(d,indent=2)+'\n')
out=['# WT1 worktree removal census','',f"Snapshot: {d['generated_utc']}. `opus/spellcheck` = `{d['main_tip']}`.",'','Read-only inspection. No production custody copies, citation edits, worktree removals, branch deletions, pushes, or network operations were performed. This is a proposal; the lead writes `docs/reviews/harness/WT1_RULING.json`.', '', '## Method and scope','', '`git merge-base --is-ancestor <candidate-tip> opus/spellcheck` returned 0 for all eight. Tracked changes use `git status --porcelain=v1 -z --untracked-files=no`. Untracked and ignored inventories use separate NUL-delimited `git ls-files --others --exclude-standard` queries, with `--ignored` for the latter. Counts include symbolic links as entries; bytes are logical lstat bytes, not allocated disk space. Symlinks are not dereferenced or charged for their external targets. Full relative inventories and cache exclusions are in `artifacts/wt1/census.json`.', '', 'Citations: offline `rg --json -n -I --hidden --no-ignore`, scanning every nonbinary text file under the six roots below (a superset of docs/configs/scripts/deploy manifests/receipts). `.git`, `__pycache__`, `.pytest_cache`, and this WT1 report/census directory are excluded. Both absolute prefixes and `~/Projects/` spellings are searched with a worktree-name boundary, avoiding l1/l1r prefix collisions. Every matching file and line is listed below; exact source lines and per-occurrence targets are retained in JSON. No hit is waived as historical: receipts and archives are conservatively treated as live until the lead rules. Binary files and symlink-directory traversal are outside this text grep.', '']
out += ['- `'+p+'`' for p in d['citation_roots']]
out += ['', '`lsof -a -d cwd -Fpcn` inspected all processes visible to this user, including cwd descendants. No candidate match was returned; visibility is limited to what lsof can observe. The removal script repeats this check. All KEEP-designated trees and every non-spellcheck tree remain outside the allowlist. The requested cleanup tree is the registered `greek-ocr-toolkit-cleanup`, not a nonexistent spellcheck-cleanup tree.', '', '## Disposition proposal','', 'Custody and repoint counts overlap. All eight need both; none is currently ready for removal. Unresolved replacement targets block execution even when ancestry is clean.', '', '| Worktree suffix | Merged | Tracked changes | Untracked count / bytes | Ignored count / bytes | Custody MB | Citing files / lines | Proposal |','|---|---|---:|---:|---:|---:|---:|---|']
for r in d['candidates']:
 out.append(f"| -{r['name'].split('spellcheck-')[1]} | yes | {r['tracked_modifications']} | {r['untracked_count']} / {r['untracked_bytes']} | {r['ignored_count']} / {r['ignored_bytes']} | {r['custody_bytes']/1e6:.3f} | {r['citation_file_count']} / {len(r['citations'])} | CUSTODY + REPOINT |")
s=d['s8_known_evidence'];out+=['', '## Known S8 LQB input','',f"`{s['relative_path']}` exists and is TRACKED in both S8 and main, with byte-identical SHA-256 `{s['main_sha256']}`. Its citation can be repointed to `{M/s['relative_path']}`. It does not exist only in S8. All citing LQB files/line numbers appear in the S8 section below.",'', '## Lead script contract and ruling format','', 'Run `bash docs/reviews/harness/wt_remove_20261017.sh --dry-run --ruling artifacts/wt1/WT1_RULING.placeholder.json` for the empty placeholder. Default mode is dry-run. Execution always reads the lead-owned `docs/reviews/harness/WT1_RULING.json`; alternate rulings are accepted only for dry-run. Logs use the same scratchpad as the merge script, with timestamp plus a unique suffix.', '', 'The ruling binds `main_tip` and `census_sha256`; each REMOVE entry binds name, branch, tip, and custody/repoint booleans. Empty `worktrees` authorizes nothing. Names outside the exact eight, drift, tracked changes, process cwd, missing/nonidentical replacements, or remaining citations fail closed. KEEP entries never remove. Only listed REMOVE entries reach `git worktree remove <path>`.', '', 'Custody preserves all untracked AND ignored entries except the two explicitly regenerable cache classes. It preserves relative paths and symlink objects without following their targets, hashes regular-file contents or symlink target bytes, verifies each copy, and writes `<name>.sha256.json` beside the custody directory. Existing destinations/manifests are refused. Originals remain untouched. **Non-ignored untracked files therefore cause ordinary Git removal to refuse, even after custody; the script aborts without retry.** The lead must separately resolve that refusal under a new explicit ruling/workflow; this script does not silently delete originals. Ignored-only caches/evidence may be discarded by ordinary Git removal, which is why ignored evidence is also copied first.', '', 'Every citation in the census must have a verified identical replacement and be repointed before removal. Directory-only, missing, dynamic, changed, or shell-variable paths are explicitly unresolved below. No replacement is asserted for those. A separate verified custody-based replacement can be proposed by the lead after custody; this snapshot must then be refreshed and re-bound. The script never edits citations.', '', 'Example ruling entry (schema illustration only, not approval):', '', '```json',json.dumps(dict(main_tip=d['main_tip'],census_sha256=hashlib.sha256(P.read_bytes()).hexdigest(),worktrees=[dict(name=d['candidates'][0]['name'],action='REMOVE',branch=d['candidates'][0]['branch'],tip=d['candidates'][0]['tip'],custody=True,repoint=True)]),indent=2),'```','', '## Per-worktree evidence','']
for r in d['candidates']:
 out += [f"### {r['name']}",'',f"Path: `{r['path']}`. Branch: `{r['branch']}`. Tip: `{r['tip']}`. Ancestor: **yes**. Tracked modifications: **0**. Process cwd matches: **0**.",'',f"Proposal: **CUSTODY-THEN-REMOVE + REPOINT-THEN-REMOVE** (pending lead ruling and unresolved citations). Custody: `{r['custody_destination']}/`, {r['custody_count']} entries, {r['custody_bytes']} bytes ({r['custody_bytes']/1e6:.3f} decimal MB).",'', 'Untracked top directories (count, logical bytes):','', '```json',json.dumps(r['untracked_top_dirs_detail'],indent=2),'```','',f"Excluded regenerable cache paths ({len(r['cache_exclusions'])}; no other cache classes excluded):",'']
 out+=['- `'+p+'`' for p in r['cache_exclusions']] or ['- None.']
 out+=['','Custody symbolic links (preserve link itself; external data is not part of the worktree):','']
 out += ['- `'+i['path']+'`' for i in r['untracked']+r['ignored'] if i['symlink']] or ['- None.']
 out+=['',f"Citations: {r['citation_file_count']} files, {len(r['citations'])} matching lines, {r['unresolved_citation_targets']} distinct unresolved targets. Each file below lists every matching line, followed by its unique target mappings. Verified replacements are byte-identical **now**, before any edits; SHA values are in JSON. BLOCKED entries have no verified replacement and cannot be blindly prefix-replaced.",'']
 groups=collections.defaultdict(list)
 for h in r['citations']:groups[h['file']].append(h)
 for file,hits in sorted(groups.items()):
  out += [f"- `{file}` — lines: "+', '.join(str(h['line']) for h in hits)+'.']
  targets={t['old']:t for h in hits for t in h['targets']}
  for old,t in sorted(targets.items()):
   if t['byte_identical']:out.append(f"  - `{old}` → `{t['replacement']}` (verified byte-identical).")
   else:out.append(f"  - `{old}` → **BLOCKED: no verified byte-identical replacement** (main counterpart checked: `{t['replacement']}`).")
  if not targets:out.append('  - BLOCKED: no concrete file target parsed; inspect the exact JSON source line.')
 out.append('')
files=len({h['file'] for r in d['candidates'] for h in r['citations']});mb=sum(r['custody_bytes'] for r in d['candidates'])/1e6
out+=['## Verification','', '25 synthetic-repository script tests passed; see `artifacts/wt1/script_tests.log`. Tests cover dry-run/no-op, clean synthetic removal with branch retention, merged/tip/branch/dirty/inventory/process guards, protected names, custody (including ignored evidence and symlinks), copy verification, Git refusal preserving original files, citation repoint/new-citation detection, and ruling/hash guards. `bash -n` also passed. The live empty-placeholder dry-run log is recorded in `artifacts/wt1/dry_run.log`. No production worktree removal was attempted.','',f'WT1 READY: candidates 8; REMOVE-CLEAN 0; CUSTODY 8 ({mb:.3f} MB); REPOINT 8 ({files} files); KEEP 0; script tests 25 passed']
(M/'docs/reviews/harness/WT1_CENSUS.md').write_text('\n'.join(out)+'\n')
placeholder=dict(description='PLACEHOLDER ONLY: no worktrees authorized; lead writes the real WT1_RULING.json',main_tip=d['main_tip'],census_sha256=hashlib.sha256(P.read_bytes()).hexdigest(),worktrees=[])
(M/'artifacts/wt1/WT1_RULING.placeholder.json').write_text(json.dumps(placeholder,indent=2)+'\n')
print('report complete',len(out),'lines;',files,'files;',mb,'MB')
